1	import Link from "next/link";
2	import InlineRichText from "@/components/InlineRichText";
3	import TagPill from "@/components/TagPill";
4	import type { StoryCard as StoryCardType } from "@/types";
5	import styles from "./StoryCard.module.css";
6	
7	interface Props {
8	  story: StoryCardType;
9	}
10	
11	const dateFormatter = new Intl.DateTimeFormat("en-US", {
12	  month: "short",
13	  day: "numeric",
14	  year: "numeric",
15	});
16	
17	function formatDate(isoString: string | null): string {
18	  if (!isoString) return "Draft";
19	  return dateFormatter.format(new Date(isoString));
20	}
21	
22	function pluralize(n: number, singular: string, plural = `${singular}s`) {
23	  return `${n} ${n === 1 ? singular : plural}`;
24	}
25	
26	export default function StoryCard({ story }: Props) {
27	  return (
28	    <Link
29	      href={`/story/${story.id}`}
30	      className={`${styles.card} ${story.isAdult ? styles.cardAdult : ""}`}
31	      data-tag-ids={story.tags.map((t) => t.id).join(" ")}
32	    >
33	      {/* 1. Title */}
34	      <h4 className={styles.title}>{story.title}</h4>
35	
36	      {/* 2. Tags — first two render as pills; anything past that
37	            collapses into a +N chip so the row stays one line and
38	            every card on the site is the same height. Inert
39	            because the card root is already a Link; nested <a>
40	            isn't valid HTML. */}
41	      <div className={styles.tags}>
42	        {story.tags.slice(0, 2).map((tag) => (
43	          <TagPill key={tag.id} tag={tag} linkable={false} />
44	        ))}
45	        {story.tags.length > 2 && (
46	          <span className={styles.tagMore}>+{story.tags.length - 2}</span>
47	        )}
48	      </div>
49	
50	      {/* 3. Excerpt — height locked even when empty */}
51	      <InlineRichText content={story.excerpt} className={styles.excerpt} />
52	
53	      {/* 4. Footer */}
54	      <div className={styles.footer}>
55	        <span>{formatDate(story.publishedAt)}</span>
56	        <span className={styles.likes}>
57	          <HeartGlyph />
58	          {pluralize(story.likeCount, "like")}
59	        </span>
60	      </div>
61	    </Link>
62	  );
63	}
64	
65	function HeartGlyph() {
66	  return (
67	    <svg
68	      className={styles.likeIcon}
69	      viewBox="0 0 24 24"
70	      fill="none"
71	      stroke="currentColor"
72	      strokeWidth="1.5"
73	      strokeLinecap="round"
74	      strokeLinejoin="round"
75	      aria-hidden="true"
76	      suppressHydrationWarning
77	    >
78	      <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" />
79	    </svg>
80	  );
81	}
