33	// ── SeriesCard ─────────────────────────────────────────────────────
34	
35	export function SeriesCard({ series }: { series: SeriesCardType }) {
36	  const chapterCount = series._count?.chapters ?? series.chapters.length;
37	  const latestChapter = series.chapters[0];
38	
39	  return (
40	    <Link
41	      href={`/series/${series.id}`}
42	      className={`${styles.card} ${series.isAdult ? styles.cardAdult : ""}`}
43	      data-tag-ids={series.tags.map((t) => t.id).join(" ")}
44	    >
45	      {/* 1. Title */}
46	      <h4 className={styles.title}>{series.title}</h4>
47	
48	      {/* 2. Series label + tags */}
49	      <p className={styles.seriesLabel}>
50	        Series · {pluralize(chapterCount, "chapter")}
51	        {series.status === "COMPLETE" && (
52	          <span className={styles.statusComplete}> · Complete</span>
53	        )}
54	        {series.status === "HIATUS" && (
55	          <span className={styles.statusHiatus}> · Hiatus</span>
56	        )}
57	      </p>
58	      <div className={styles.tags}>
59	        {series.tags.slice(0, 2).map((tag) => (
60	          <TagPill key={tag.id} tag={tag} linkable={false} />
61	        ))}
62	        {series.tags.length > 2 && (
63	          <span className={styles.tagMore}>+{series.tags.length - 2}</span>
64	        )}
65	      </div>
66	
67	      {/* 3. Excerpt — fixed-height block */}
68	      <InlineRichText content={series.excerpt} className={styles.excerpt} />
69	
70	      {/* Optional latest-chapter line */}
71	      {latestChapter && (
72	        <p className={styles.latestChapter}>Latest: {latestChapter.title}</p>
73	      )}
74	
75	      {/* 4. Footer */}
76	      <div className={styles.footer}>
77	        <span>{chapterCount === 0 ? "No chapters yet" : ""}</span>
78	        <span className={styles.likes}>
79	          <HeartGlyph />
80	          {pluralize(series.likeCount, "like")}
81	        </span>
82	      </div>
83	    </Link>
84	  );
85	}
