107	        {chapter.tags.length > 2 && (
108	          <span className={styles.tagMore}>+{chapter.tags.length - 2}</span>
109	        )}
110	      </div>
111	
112	      {/* 3. Excerpt — fixed-height block */}
113	      <InlineRichText content={chapter.excerpt} className={styles.excerpt} />
