3	import { useRef } from "react";
4	import { gsap, prefersReducedMotion, useGSAP } from "@/lib/gsap";
5	import { ScrollTrigger } from "gsap/ScrollTrigger";
6	import styles from "./CardGrid.module.css";
7	
8	/**
9	 * Grid wrapper for sections that should fill the container width
10	 * (auto-fill, minmax(280px, 1fr)). Same GSAP stagger reveal as CardRow
11	 * so the visual rhythm matches.
12	 */
13	export default function CardGrid({ children }: { children: React.ReactNode }) {
14	  const containerRef = useRef<HTMLDivElement>(null);
15	
16	  useGSAP(
17	    () => {
18	      if (!containerRef.current) return;
19	      if (prefersReducedMotion()) return;
20	      const cards = Array.from(containerRef.current.children);
21	      if (cards.length === 0) return;
22	
23	      gsap.from(cards, {
24	        opacity: 0,
25	        y: 30,
26	        stagger: 0.08,
27	        duration: 0.5,
28	        ease: "power2.out",
29	        scrollTrigger: {
30	          trigger: containerRef.current,
31	          start: "top 85%",
32	          once: true,
33	        },
34	      });
35	    },
36	    { scope: containerRef },
37	  );
38	
39	  void ScrollTrigger;
40	
41	  return (
42	    <div ref={containerRef} className={styles.grid}>
43	      {children}
44	    </div>
45	  );
46	}
