1	.grid {
2	  display: grid;
3	  /* min(100%, 280px) makes the cards collapse to full container width
4	     on viewports narrower than 280px, so a phone never gets a card
5	     wider than the viewport. On wider screens, each cell is at least
6	     280px wide. */
7	  grid-template-columns: repeat(auto-fill, minmax(min(100%, 280px), 1fr));
8	  gap: 16px;
9	}
10	
11	/* Cards inside the grid should stretch to fill their cell instead of
12	   capping at 320px like they do in horizontal-scroll rows. */
13	.grid > * {
14	  max-width: none;
15	  width: 100%;
16	  min-width: 0;
17	}
