1	"use client";
2	
3	import { useRef, useState } from "react";
4	import { gsap, prefersReducedMotion, useGSAP } from "@/lib/gsap";
5	import { ScrollTrigger } from "gsap/ScrollTrigger";
6	import styles from "./ExpandableSection.module.css";
7	
8	interface Props {
9	  title: string;
10	  children: React.ReactNode;
11	  /** Hide the See all toggle when the section is small enough that
12	      everything's already visible in one row. */
13	  expandable?: boolean;
14	}
15	
16	/**
17	 * Default state is a single horizontally scrollable row of cards.
18	 * Clicking "See all" flips the layout to a multi-row grid in place,
19	 * showing every card without leaving the page. "Collapse" returns to
20	 * the row.
21	 */
22	export default function ExpandableSection({
23	  title,
24	  children,
25	  expandable = true,
26	}: Props) {
27	  const [expanded, setExpanded] = useState(false);
28	  const containerRef = useRef<HTMLDivElement>(null);
29	
30	  useGSAP(
31	    () => {
32	      if (!containerRef.current) return;
33	      if (prefersReducedMotion()) return;
34	      const cards = Array.from(containerRef.current.children);
35	      if (cards.length === 0) return;
36	      // Fade-only — earlier we also translated each card up from y:30,
37	      // but during the staggered reveal that produces a brief moment
38	      // where cards land at uneven heights. Opacity stagger reads as
39	      // crisp without ever desyncing the row.
40	      gsap.from(cards, {
41	        opacity: 0,
42	        stagger: 0.06,
43	        duration: 0.4,
44	        ease: "power2.out",
45	        scrollTrigger: {
46	          trigger: containerRef.current,
47	          start: "top 85%",
48	          once: true,
49	        },
50	      });
51	    },
52	    { scope: containerRef, dependencies: [] },
53	  );
54	
55	  // The import side-effect registers the plugin via lib/gsap.ts.
56	  void ScrollTrigger;
57	
58	  return (
59	    <section className={styles.section}>
60	      <header className={styles.header}>
61	        {/* h2 so the heading hierarchy doesn't skip from the page
62	            h1 straight to h3 — flagged by axe on chapter / story /
63	            homepage. ExpandableSection is always a top-level
64	            subsection wherever it's used. */}
65	        <h2 className={styles.title}>{title}</h2>
66	        {expandable && (
67	          <button
68	            type="button"
69	            onClick={() => setExpanded((e) => !e)}
70	            className={styles.toggle}
71	            aria-expanded={expanded}
72	          >
73	            {expanded ? "Collapse" : "See all"}
74	          </button>
75	        )}
76	      </header>
77	      <div
78	        ref={containerRef}
79	        className={expanded ? styles.expanded : styles.row}
80	      >
81	        {children}
82	      </div>
83	    </section>
84	  );
85	}
