1	.section {
2	  display: flex;
3	  flex-direction: column;
4	  gap: var(--gap-section-title);
5	}
6	
7	.header {
8	  display: flex;
9	  align-items: baseline;
10	  justify-content: space-between;
11	  gap: 16px;
12	}
13	
14	.title {
15	  font-family: var(--font-display);
16	  font-size: var(--fs-section);
17	  font-weight: 600;
18	  margin: 0;
19	  color: var(--text);
20	}
21	
22	.toggle {
23	  background: transparent;
24	  border: none;
25	  color: var(--text-muted);
26	  font-family: var(--font-ui);
27	  font-size: var(--fs-ui-sm);
28	  font-weight: 500;
29	  letter-spacing: 0.02em;
30	  cursor: pointer;
31	  padding: 4px 10px;
32	  border-radius: var(--radius-pill);
33	  transition:
34	    color var(--transition-fast),
35	    background var(--transition-fast);
36	  flex-shrink: 0;
37	  white-space: nowrap;
38	}
39	.toggle:hover {
40	  color: var(--gold);
41	  background: var(--gold-dim);
42	}
43	
44	/* Default — single horizontally-scrollable row.
45	
46	   The row bleeds past the page's horizontal padding so cards can run
47	   to the viewport edge instead of being abruptly cut at the container
48	   boundary; matching padding-right keeps the last card from sitting
49	   flush against the screen edge.
50	
51	   The mask-image fade on the right tells readers there's more to
52	   scroll into and softens the off-screen cut visually — same trick
53	   as TagBar.
54	
55	   Top + side padding gives the hover lift (-2px translateY) breathing
56	   room so the lifted edge isn't clipped. */
57	.row {
58	  display: flex;
59	  align-items: stretch;
60	  gap: 16px;
61	  overflow-x: auto;
62	  overflow-y: hidden;
63	  padding: 6px var(--pad-x) 16px;
64	  margin: 0 calc(-1 * var(--pad-x));
65	  scrollbar-width: none;
66	  -webkit-mask-image: linear-gradient(
67	    to right,
68	    var(--bg) 0%,
69	    var(--bg) 94%,
70	    transparent 100%
71	  );
72	  mask-image: linear-gradient(
73	    to right,
74	    var(--bg) 0%,
75	    var(--bg) 94%,
76	    transparent 100%
77	  );
78	}
79	.row::-webkit-scrollbar {
80	  display: none;
81	}
82	
83	/* Expanded — grid that fills the container width, auto-fills as many
84	   columns as fit at 280-1fr. Cards override their flex-row max-width
85	   so they stretch to fill the cell instead of leaving gaps. */
86	.expanded {
87	  display: grid;
88	  grid-template-columns: repeat(auto-fill, minmax(min(100%, 280px), 1fr));
89	  gap: 16px;
90	  padding: 6px 4px 16px;
91	}
92	.expanded > * {
93	  max-width: none;
94	  width: 100%;
95	  min-width: 0;
96	}
97	
98	@media (max-width: 720px) {
99	  /* Match the mobile page padding so the bleed lines up with the
100	     viewport edge on phones. */
101	  .row {
102	    padding: 6px var(--pad-x-mobile) 16px;
103	    margin: 0 calc(-1 * var(--pad-x-mobile));
104	  }
105	}
