1	"use client";
2	
3	import Link from "next/link";
4	import type { ContinueReadingItem } from "@/lib/api";
5	import styles from "./ContinueCard.module.css";
6	
7	interface Props {
8	  item: ContinueReadingItem;
9	  onRemove: () => void;
10	}
11	
12	/**
13	 * Single card in the "Pick up where you left off" row. Combines:
14	 *   - Link to the chapter/story (optionally with `?page=N` so the
15	 *     paged reader lands on the same page the visitor was on).
16	 *   - "{percent}% read" badge and chapter / series subtitle.
17	 *   - Small X button that fires `onRemove()` — the parent does the
18	 *     optimistic UI removal + the DELETE.
19	 *
20	 * Kept presentational; all of the state + the API call live one
21	 * level up in `ResumeReadingRow`.
22	 */
23	export default function ContinueCard({ item, onRemove }: Props) {
24	  const isChapter = item.contentType === "chapter";
25	  const href =
26	    item.pageNumber && item.pageNumber > 1
27	      ? `/${item.contentType}/${item.id}?page=${item.pageNumber}`
28	      : `/${item.contentType}/${item.id}`;
29	  const percent = Math.max(0, Math.min(100, Math.round(item.scrollPercentage)));
30	
31	  return (
32	    <article className={styles.card}>
33	      <Link href={href} className={styles.link}>
34	        {isChapter && item.orderIndex !== undefined && (
35	          <span className={styles.partLabel}>Part {item.orderIndex}</span>
36	        )}
37	        <span className={styles.title}>{item.title}</span>
38	        {isChapter && item.series && (
39	          <span className={styles.seriesTitle}>{item.series.title}</span>
40	        )}
41	        <span className={styles.badge}>
42	          {/* The chapter/page metadata lives in the link's main text;
43	              the badge focuses on the % read so it reads as a "where
44	              you stopped" hint, not a duplicate title. */}
45	          <span className={styles.badgePct}>{percent}%</span> read
46	        </span>
47	      </Link>
48	      <button
49	        type="button"
50	        onClick={(e) => {
51	          // The button is positioned absolutely on top of the link
52	          // — the bubble would still hit the <Link>'s click handler
53	          // and navigate the reader away.
54	          e.preventDefault();
55	          e.stopPropagation();
56	          onRemove();
57	        }}
58	        className={styles.remove}
59	        aria-label={`Remove ${item.title} from continue reading`}
60	      >
61	        <XIcon />
62	      </button>
63	    </article>
64	  );
65	}
66	
67	function XIcon() {
68	  return (
69	    <svg
70	      viewBox="0 0 24 24"
71	      width="12"
72	      height="12"
73	      fill="none"
74	      stroke="currentColor"
75	      strokeWidth="2"
76	      strokeLinecap="round"
77	      strokeLinejoin="round"
78	      aria-hidden="true"
79	      suppressHydrationWarning
80	    >
81	      <line x1="18" y1="6" x2="6" y2="18" />
82	      <line x1="6" y1="6" x2="18" y2="18" />
83	    </svg>
84	  );
85	}
