1	"use client";
2	
3	import Link from "next/link";
4	import { useEffect, useState } from "react";
5	import { listProgress, type ProgressEntry } from "@/lib/readingProgress";
6	import styles from "./ContinueReadingRow.module.css";
7	
8	/**
9	 * Homepage section that lists the series the reader is mid-way
10	 * through, sorted most-recent first. Renders nothing if there's no
11	 * stored progress yet, so first-time visitors see the regular feed
12	 * straight away.
13	 */
14	export default function ContinueReadingRow({ limit = 6 }: { limit?: number }) {
15	  const [entries, setEntries] = useState<ProgressEntry[] | null>(null);
16	
17	  useEffect(() => {
18	    setEntries(listProgress().slice(0, limit));
19	  }, [limit]);
20	
21	  // Server render + first paint while we read localStorage — both
22	  // produce nothing so there's no layout flicker.
23	  if (!entries || entries.length === 0) return null;
24	
25	  return (
26	    <section className={styles.section} aria-label="Continue reading">
27	      <header className={styles.header}>
28	        {/* h2 mirrors the level used by sibling homepage sections
29	            (ExpandableSection) so the document outline reads
30	            "Continue reading / New stories / Most read / ..." at the
31	            same heading rank. */}
32	        <h2 className={styles.title}>Continue reading</h2>
33	      </header>
34	      <ul className={styles.list}>
35	        {entries.map((entry) => (
36	          <li key={entry.seriesId}>
37	            <Link
38	              href={`/chapter/${entry.chapterId}`}
39	              className={styles.card}
40	            >
41	              <span className={styles.partLabel}>
42	                Part {entry.chapterOrderIndex}
43	              </span>
44	              <span className={styles.chapterTitle}>{entry.chapterTitle}</span>
45	              <span className={styles.seriesTitle}>{entry.seriesTitle}</span>
46	            </Link>
47	          </li>
48	        ))}
49	      </ul>
50	    </section>
51	  );
52	}
