13	/**
14	 * Logged-in-only personalized row that sits above Latest on the
15	 * homepage. The single backend round trip returns both the
16	 * personalized feed (or null when the reader hasn't crossed the
17	 * cold-start threshold yet) and the trending fallback, so we can
18	 * render whichever is appropriate without a second request.
19	 *
20	 * Renders nothing for anonymous readers — the homepage stays
21	 * exactly as it always was for them.
22	 */
23	export default function RecommendationsRow() {
24	  const auth = useAuth();
25	  const [data, setData] = useState<HomepageRecommendations | null>(null);
26	
27	  useEffect(() => {
28	    if (auth.status !== "authenticated") {
29	      // Reset when the reader signs out so a stale "For you" row
30	      // doesn't bleed into the next session on the same device.
31	      setData(null);
32	      return;
33	    }
34	    let cancelled = false;
35	    void getHomepageRecommendations()
36	      .then((d) => {
37	        if (!cancelled) setData(d);
38	      })
39	      .catch(() => {
40	        // Recommendations are non-critical — silent failure keeps
41	        // the rest of the homepage rendering normally.
42	      });
43	    return () => {
44	      cancelled = true;
45	    };
46	  }, [auth.status]);
47	
48	  if (auth.status !== "authenticated") return null;
49	  if (!data) return null;
50	
51	  // Prefer the personalized feed; fall back to trending when the
52	  // reader is still in cold-start. Empty results render nothing —
53	  // there's no point showing an empty section with a heading.
54	  const items = data.forYou ?? data.trending;
55	  if (items.length === 0) return null;
