59	  return (
60	    <ExpandableSection title={title} expandable={items.length > 4}>
61	      {items.map((item) =>
62	        item.type === "story" ? (
63	          <StoryCard key={item.id} story={item} />
64	        ) : (
65	          <ChapterCard key={item.id} chapter={item} />
66	        ),
67	      )}
68	    </ExpandableSection>
69	  );
70	}
