1	import ExpandableSection from "@/components/ExpandableSection";
2	import { ChapterCard, SeriesCard } from "@/components/SeriesCard";
3	import StoryCard from "@/components/StoryCard";
4	import { getSeriesList, getStories } from "@/lib/api";
5	import type { SeriesCard as SeriesCardType, StoryCard as StoryCardType } from "@/types";
6	
7	interface Props {
8	  tagIds: string[];
9	  /** Current item — filtered out of the results so we don't suggest it back. */
10	  excludeId: string;
11	  /** "story" excludes story id, "series" excludes series id, "chapter" excludes the chapter id from story results but needs `excludeSeriesId` to keep the parent series out of the series column. */
12	  excludeType: "story" | "series" | "chapter";
13	  /**
14	   * When rendering "more like this" on a chapter page, the parent
15	   * series shares the same tags and would otherwise rank first in
16	   * the series column. Pass the parent series id here so it's
17	   * filtered out. Stories and series pages don't need it.
18	   */
19	  excludeSeriesId?: string;
20	  limit?: number;
21	}
22	
23	type Scored<T> = T & { __score: number };
24	
25	function score<T extends { tags: { id: string }[] }>(
26	  item: T,
27	  needle: Set<string>,
28	): Scored<T> {
29	  let s = 0;
30	  for (const t of item.tags) if (needle.has(t.id)) s++;
31	  return { ...item, __score: s };
32	}
33	
34	/**
35	 * Renders a row of related stories + series sharing tags with the
36	 * current item. No-op when the current item has no tags or the API
37	 * returns nothing — callers can drop it in unconditionally.
38	 */
39	export default async function RelatedSection({
40	  tagIds,
41	  excludeId,
42	  excludeType,
43	  excludeSeriesId,
44	  limit = 6,
45	}: Props) {
46	  if (tagIds.length === 0) return null;
47	
48	  const [storiesRes, seriesRes] = await Promise.all([
49	    getStories({ tagIds, limit: 24 }).catch(() => ({
50	      data: [] as StoryCardType[],
51	      meta: { total: 0, page: 1, limit: 24, totalPages: 0 },
52	    })),
53	    getSeriesList({ tagIds, limit: 24 }).catch(() => ({
54	      data: [] as SeriesCardType[],
55	      meta: { total: 0, page: 1, limit: 24, totalPages: 0 },
56	    })),
57	  ]);
58	
59	  const needle = new Set(tagIds);
60	
61	  const stories = storiesRes.data
62	    .filter((s) => !(excludeType === "story" && s.id === excludeId))
63	    .map((s) => score(s, needle));
64	
65	  const series = seriesRes.data
66	    // Two exclusion paths for the series column:
67	    //  1. excludeType === "series" — we're on a series page, drop self.
68	    //  2. excludeSeriesId set — we're on a chapter page, drop the
69	    //     parent series (it shares all the chapter's tags and would
70	    //     otherwise top the column on its own chapter's recommendations).
71	    .filter(
72	      (sr) =>
73	        !(excludeType === "series" && sr.id === excludeId) &&
74	        sr.id !== excludeSeriesId,
75	    )
76	    .map((sr) => score(sr, needle));
77	
78	  // Interleave by score so the most overlap-rich items surface first
79	  // regardless of whether they're a story or a series.
80	  const combined: Array<
81	    | { kind: "story"; item: Scored<StoryCardType> }
82	    | { kind: "series"; item: Scored<SeriesCardType> }
83	  > = [
84	    ...stories.map((item) => ({ kind: "story" as const, item })),
85	    ...series.map((item) => ({ kind: "series" as const, item })),
86	  ].sort((a, b) => b.item.__score - a.item.__score);
87	
88	  const top = combined.slice(0, limit);
89	  if (top.length === 0) return null;
90	
91	  return (
92	    <ExpandableSection title="More like this" expandable={top.length > 4}>
93	      {top.map((entry) =>
94	        entry.kind === "story" ? (
95	          <StoryCard key={`s-${entry.item.id}`} story={entry.item} />
96	        ) : (
97	          <SeriesCard key={`r-${entry.item.id}`} series={entry.item} />
98	        ),
99	      )}
100	    </ExpandableSection>
101	  );
102	}
