124	function describeSearch({
125	  search,
126	  tagIds,
127	  tags,
128	  totalCount,
129	}: {
130	  search?: string;
131	  tagIds?: string[];
132	  tags: { id: string; name: string }[];
133	  totalCount: number;
134	}): string {
135	  const parts: string[] = [];
136	  if (search) parts.push(`for "${search}"`);
137	  if (tagIds && tagIds.length > 0) {
138	    const names = tagIds
139	      .map((id) => tags.find((t) => t.id === id)?.name)
140	      .filter((n): n is string => !!n);
141	    if (names.length > 0) {
142	      parts.push(`tagged ${names.map((n) => `#${n}`).join(", ")}`);
143	    }
144	  }
145	  if (parts.length === 0) {
146	    return totalCount === 1
147	      ? "1 published piece"
148	      : `${totalCount} published pieces`;
149	  }
150	  return `${totalCount} ${totalCount === 1 ? "result" : "results"} ${parts.join(" ")}`;
151	}
