98	          keywords: story.tags.map((t) => t.name).join(", "),
99	        }}
100	      />
101	      <NsfwModal
102	        title={story.title}
103	        tags={story.tags}
104	        isAdult={story.isAdult}
105	        contentId={story.id}
106	      />
107	      {/* Polyfill that mirrors Chromium's native Text Fragments
108	          scroll-and-highlight for Firefox + Safari so shared
109	          `#:~:text=...` links land readers on the passage. */}
110	      <TextFragmentScroller />
111	      <SiteHeader />
112	
113	      {/* `id="main"` is the skip-link target. `tabIndex={-1}` makes
114	          the landmark programmatically focusable so the next Tab
115	          after the skip-link lands on a control inside the page. */}
116	      <main id="main" tabIndex={-1}>
117	      <article className={styles.article}>
118	        <div className={styles.headerToContent}>
119	          {story.tags.length > 0 && (
120	            <div className={styles.tags}>
121	              {story.tags.map((tag) => (
122	                <TagPill key={tag.id} tag={tag} reading />
123	              ))}
124	            </div>
125	          )}
126	
127	          <h1 className={styles.title}>{story.title}</h1>
128	
129	          <div className={styles.meta}>
130	            <span>{dateFormatter.format(new Date(story.publishedAt))}</span>
131	            <span className={styles.metaSep}>·</span>
132	            <ReadTime baseMinutes={story.estimatedReadMinutes} unit="min read" />
133	            <span className={styles.metaSep}>·</span>
134	            <span>
135	              {story.likeCount} {story.likeCount === 1 ? "like" : "likes"}
136	            </span>
137	          </div>
138	
139	          {story.isAuthorsChoice && story.authorsNote && (
140	            <aside className={styles.authorsNote}>
141	              <p className={styles.authorsNoteLabel}>Author&rsquo;s Note</p>
142	              <RichText
143	                content={story.authorsNote}
144	                className={styles.authorsNoteBody}
145	              />
146	            </aside>
147	          )}
148	        </div>
149	
150	        {story.epigraph && (
151	          <RichText
152	            content={story.epigraph}
153	            className={styles.epigraph}
154	          />
155	        )}
156	
157	        <ReadingView
158	          contentType="story"
159	          contentId={story.id}
160	          initialContent={story.content}
161	          initialPage={story.page}
162	          totalPages={story.totalPages}
163	          shareTitle={story.title}
164	          shareUrl={`${SITE_URL}/story/${story.id}`}
165	        />
166	
167	        <footer className={styles.footer}>
168	          <LikeButton
169	            contentType="story"
170	            contentId={story.id}
171	            initialCount={story.likeCount}
172	          />
173	          <SaveButton contentType="story" contentId={story.id} />
174	          <ShareButton
175	            title={story.title}
176	            text={stripHtml(story.excerpt)}
177	          />
178	        </footer>
179	      </article>
180	
181	      <div className={styles.relatedWrap}>
182	        <RelatedSection
183	          tagIds={story.tags.map((t) => t.id)}
184	          excludeId={story.id}
185	          excludeType="story"
186	        />
187	      </div>
188	      </main>
189	    </div>
190	  );
191	}
